// Response parsing helpers
/**
 * Parses a Google Generative Language response into the unified format.
 *
 * @remarks
 * Handles Google's unique response structure with candidates and content parts.
 * Extracts both text content and functionCall parts for tool invocation.
 * Includes error handling for API errors and empty candidate arrays.
 *
 * @param data - The raw response from Google's generateContent API.
 * @param model - The model identifier to include in the response.
 * @returns A ChatResponse object in the unified format.
 * @throws Error if the response contains an API error.
 */
function parseGoogleResponse(data, model) {
    // Handle API errors
    if (data.error) {
        throw new Error(`Google API error: ${data.error.message}`);
    }
    // Handle prompt blocked by safety filters
    if (data.promptFeedback?.blockReason) {
        return {
            content: `[Response blocked: ${data.promptFeedback.blockReason}]`,
            model,
            finishReason: "stop",
        };
    }
    // Handle empty candidates
    if (!data.candidates || data.candidates.length === 0) {
        return {
            content: "[No response generated]",
            model,
            finishReason: "stop",
        };
    }
    // Check if candidate was blocked for safety
    const candidate = data.candidates[0];
    if (candidate.finishReason === "SAFETY") {
        return {
            content: "[Response blocked for safety reasons]",
            model,
            finishReason: "stop",
        };
    }
    // Handle malformed function call - model tried to use a tool incorrectly
    if (candidate.finishReason === "MALFORMED_FUNCTION_CALL") {
        const finishMessage = candidate
            .finishMessage;
        // Extract the code the model was trying to run
        const codeMatch = finishMessage?.match(/Malformed function call: (.+)/s);
        const attemptedCode = codeMatch?.[1]?.trim();
        if (attemptedCode) {
            return {
                content: `I tried to calculate this but encountered a formatting issue. Here's the code I wanted to run:\n\n\`\`\`python\n${attemptedCode}\n\`\`\`\n\nYou can run this yourself, or I can try a different approach.`,
                model,
                finishReason: "stop",
            };
        }
        return {
            content: "[Model attempted an invalid tool call. Please rephrase your request.]",
            model,
            finishReason: "stop",
        };
    }
    const parts = candidate.content?.parts ?? [];
    const text = parts.find((p) => p.text)?.text;
    const functionCalls = parts.filter((p) => p.functionCall);
    const toolCalls = functionCalls.length > 0
        ? functionCalls.map((part, index) => ({
            id: `call_${index}`,
            name: part.functionCall.name,
            arguments: part.functionCall.args,
            thoughtSignature: part.thoughtSignature,
        }))
        : undefined;
    return {
        content: text ?? null,
        toolCalls,
        usage: data.usageMetadata
            ? {
                promptTokens: data.usageMetadata.promptTokenCount,
                completionTokens: data.usageMetadata.candidatesTokenCount,
                totalTokens: data.usageMetadata.totalTokenCount,
            }
            : undefined,
        model,
        finishReason: toolCalls ? "tool_calls" : "stop",
    };
}
/**
 * Parses an Ollama chat response into the unified format.
 *
 * @remarks
 * Extracts content and tool calls from Ollama's response structure.
 * Handles both simple text responses and tool call responses.
 *
 * @param data - The raw response from Ollama's chat API.
 * @param model - The model identifier to include in the response.
 * @returns A ChatResponse object in the unified format.
 */
function parseOllamaResponse(data, model) {
    const toolCalls = data.message.tool_calls?.map((tc, index) => ({
        id: tc.id ?? `call_${index}`,
        name: tc.function.name,
        arguments: tc.function.arguments,
    }));
    return {
        content: data.message.content || null,
        toolCalls,
        model,
        finishReason: toolCalls && toolCalls.length > 0 ? "tool_calls" : "stop",
    };
}
